    if (!dragging) return;
    dragging = false;
    const p = pt(e);
    app.model?.onPointer?.(app.state, {
      type: "up",
      x: p.x,
      y: p.y,
      button: e.button,
      altKey: !!e.altKey,
      shiftKey: !!e.shiftKey
    });
